function rootItem(role,suffix,operation,radicand,expected,lessons,fields={}){
 const rootTex=operation==='cube-root'?'\\sqrt[3]{'+scalar(radicand)+'}':'\\sqrt{'+scalar(radicand)+'}';
 const square=operation==='square-roots';
 const result=square?'\\pm '+scalar(expected):scalar(expected);
 return Q(role,suffix,lessons,B(square?'Find all square roots of '+M(scalar(radicand))+'.':'Evaluate '+M(rootTex)+'.',square?'求 '+M(scalar(radicand))+' 的全部平方根。':'計算 '+M(rootTex)+'。'),B(M(result)+'.',M(result)+'。'),[
  [operation==='cube-root'?'A cube root cubes to the given number.':square?'For a positive radicand, both opposite values have the required square.':'The radical symbol denotes the nonnegative square root.',operation==='cube-root'?'立方根的立方等於被開方數。':square?'正數的兩個互為相反數的值，平方都等於被開方數。':'平方根號表示非負算術平方根。'],
  ['Check '+M('('+scalar(expected)+')^{'+(operation==='cube-root'?3:2)+'}='+scalar(radicand))+'.'+(square?' The negative of this nonzero root has the same square.':''),'核對 '+M('('+scalar(expected)+')^{'+(operation==='cube-root'?3:2)+'}='+scalar(radicand))+'。'+(square?' 該非零根的相反數平方也相同。':'')]
  ],{type:square?'short':'numeric',...(!square?{numericAnswer:num(expected)}:{}),answerExpression:result,audit:{kind:'root',operation,radicand:String(radicand),expected:String(expected),...(square?{solutions:[String(expected),'-'+String(expected)]}:{})},hints:[
  B('Identify whether the task asks for square roots, a principal square root, or a cube root.','辨認題目問平方根、算術平方根，還是立方根。'),
  B(operation==='cube-root'?'A negative radicand has a negative cube root.':square?'A positive number has two opposite square roots.':'The principal square root cannot be negative.',operation==='cube-root'?'負數的立方根是負數。':square?'正數有兩個互為相反數的平方根。':'算術平方根不能是負數。'),
  B('Raise each proposed answer to the required power and check the original radicand.','把各候選答案乘方，核對原被開方數。')
 ],...fields});
}
