function modelSystem(role,suffix,lessons,matrix,prompt,context,fields={}){
 const solved=systemSteps(matrix,['x','y']);
 return system(role,suffix,lessons,matrix,{prompt,expression:undefined,steps:[B('With the stated variable meanings, the two independent conditions give '+M(systemTex(matrix,['x','y']))+'.','依所設未知數，兩個獨立條件給 '+M(systemTex(matrix,['x','y']))+'。'),...solved.steps,B('Interpret both values in the stated units and check any nonnegative or integer restrictions.','按題意解釋兩值及單位，核對非負或整數限制。')],audit:{kind:'linear-system',variables:['x','y'],matrix:matrix.map(r=>r.map(String)),solution:solved.solution,method:'elimination',context},...fields});
}
function countCost(role,suffix,total,prices,cost,lessons=[31,33],fields={}){
 return modelSystem(role,suffix,lessons,[[1,1,total],[...prices,cost]],B('A tickets cost '+prices[0]+' dollars each and B tickets '+prices[1]+' dollars each. '+total+' tickets cost '+cost+' dollars. Let x and y be the numbers of A and B tickets. Form and solve a system; check whole nonnegative counts.','A 票每張 '+prices[0]+' 元，B 票每張 '+prices[1]+' 元。共 '+total+' 張，收入 '+cost+' 元。設 x、y 分別為 A、B 票張數，列方程組求解，核對非負整數限制。'),{kind:'count-cost',total:String(total),unitPrices:prices.map(String),totalCost:String(cost),integerCounts:true,...fields.context},fields);
}
function purchases(role,suffix,coeffs,bills,lessons=[31],fields={}){
 const matrix=coeffs.map((r,i)=>[...r,bills[i]]);
 return modelSystem(role,suffix,lessons,matrix,B('A notebook costs x dollars and a pen y dollars. '+coeffs[0][0]+' notebooks and '+coeffs[0][1]+' pens cost '+bills[0]+' dollars; '+coeffs[1][0]+' notebooks and '+coeffs[1][1]+' pens cost '+bills[1]+' dollars. Find both unit prices.','筆記簿每本 x 元，筆每支 y 元。'+coeffs[0][0]+' 本筆記簿及 '+coeffs[0][1]+' 支筆共 '+bills[0]+' 元；'+coeffs[1][0]+' 本及 '+coeffs[1][1]+' 支共 '+bills[1]+' 元。求兩種單價。'),{kind:'two-purchases',quantities:coeffs.map(r=>r.map(String)),bills:bills.map(String),positivePrices:true},fields);
}
function boat(role,suffix,down,up,lessons=[31,32]){
 return modelSystem(role,suffix,lessons,[[1,1,down],[1,-1,up]],B('A boat travels downstream at '+down+' km/h and upstream at '+up+' km/h. Let x be its still-water speed and y the current speed, both in km/h. Find x and y.','船順流速度為 '+down+' km/h，逆流速度為 '+up+' km/h。設靜水船速為 x、水流速度為 y，單位均為 km/h，求 x、y。'),{kind:'boat-speed',downstream:String(down),upstream:String(up),positiveSpeeds:true});
}
