function statsCalc(role,suffix,lessons,counts,request,index,expected,prompt,fields={}){
 const total=counts.reduce((a,b)=>a+b,0),count=counts[index],factor=request==='percent'?100:request==='sector-angle'?360:request==='estimate'?fields.population:1,expression=request==='total'?counts.join('+'):'('+count+'/'+total+')*'+factor;
 const method=request==='total'?['Add the mutually exclusive category counts: '+M(counts.join('+'))+'.','把互斥類別的頻數相加：'+M(counts.join('+'))+'。']:['Use '+M('\\frac{'+count+'}{'+total+'}')+(request==='sector-angle'?' of the full 360° circle.':request==='percent'?' ×100% to express a percentage.':request==='estimate'?' of the stated population to obtain an estimate.':' as the relative frequency.'),'用 '+M('\\frac{'+count+'}{'+total+'}')+(request==='sector-angle'?' 乘全圓的 360°。':request==='percent'?' 乘 100% 表示百分率。':request==='estimate'?' 乘指定總體數量得到估計。':' 表示頻率。')];
 return calc(role,suffix,lessons,prompt,expression,expected,[['The given categories account for every observation exactly once.','所給類別把每次觀察恰好記錄一次。'],method,['The requested result is '+M(scalar(expected))+(request==='estimate'?'; this is an estimate, not a census count.':'.'),'所求為 '+M(scalar(expected))+(request==='estimate'?'，這是估計，不是全面調查的確數。':'。')]],{audit:{kind:'statistics',counts:counts.map(String),request,index,...(request==='estimate'?{totalPopulation:String(fields.population)}:{}),expected:String(expected)},...fields});
}
function survey(role,suffix,lessons,prompt,answer,steps,rule,facts,valid=true,fields={}){
 return Q(role,suffix,lessons,prompt,answer,steps,{skill:'survey-reasoning',audit:{kind:'survey',rule,facts,valid},hints:[B('Identify the target population and the exact way participants are selected.','辨認目標總體及實際選人方法。'),B('Ask who has no chance or a different chance of selection.','想想哪些人沒有機會或有不同機會被選。'),B('Distinguish a sound sampling design from a guarantee that one realised sample is exact.','分清合理抽樣設計與保證一次樣本完全準確。')],...fields});
}
