function histogramAudit(values,bins,height,request,expected){return {kind:'histogram',...(values?{values:values.map(String)}:{}),bins:bins.map(b=>({lo:String(b.lo),hi:String(b.hi),frequency:String(b.frequency),hiClosed:!!b.hiClosed})),height,heights:bins.map(b=>height==='density'?String(b.frequency)+'/'+String(b.hi-b.lo):String(b.frequency)),request,expected};}
